    /*
     * Add to the JobProfiles
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Competency
     */
    public Competency addToJobProfiles( UUID parentId, JobProfile addTo ) {
	    LOGGER.info("handling AssignJobProfilesToCompetencyEvent - " );
	    
	    Competency parentEntity = repository.findById(parentId).get();
	    JobProfile child = registry.project( JobProfile.class, addTo.getJobProfileId());
	    
	    parentEntity.getJobProfiles().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the JobProfiles
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Competency
     */
	public Competency removeFromJobProfiles( UUID parentId, JobProfile removeFrom ) {
	    LOGGER.info("handling RemoveJobProfilesFromCompetencyEvent " );
	
	    Competency parentEntity = repository.findById(parentId).get();
	    JobProfile child = registry.project( JobProfile.class, removeFrom.getJobProfileId());
	    
	    parentEntity.getJobProfiles().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

